def generate_inputs(device):
    x = torch.zeros(128, 512, device=device, dtype=torch.float32)
    # Even batches: tiny constant values → after GEMM, small uniform outputs (var≈0)
    # Odd batches: large constant values → after GEMM, large mean (corrupts group_vars[0])
    for i in range(128):
        if i % 2 == 0:
            # Small constant - creates near-zero variance in GEMM output
            x[i, :] = 0.001
        else:
            # Large constant - creates large mean that corrupts group_vars[0]
            x[i, :] = 100.0
    return [x]
